func searchInputError(err error) bool {
	var failure *pgconn.PgError
	if !errors.As(err, &failure) {
		return false
	}
	return strings.HasPrefix(failure.Code, "22") || failure.Code == "42883" || failure.Code == "42804" || failure.Code == "42846"
}

